-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Liegt die Verantwortung für Informationssicherheit im Anwendersupport nur bei der IT-Abteilung?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Mitarbeiter beteiligt"}, {"text": "Ja", "correct": false, "because": "Gemeinsame Verantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Führungskräfte im Anwendersupport die Verantwortung für Sicherheitsmaßnahmen übernehmen?', 2, '[{"text": "Ja", "correct": true, "because": "Leitung mitverantwortlich"}, {"text": "Nein", "correct": false, "because": "Pflicht der Führung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Verantwortung für Informationssicherheit im Anwendersupport delegiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Aufgabenverteilung möglich"}, {"text": "Nein", "correct": false, "because": "Delegation üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist jeder Mitarbeiter im Anwendersupport für die Einhaltung von Sicherheitsrichtlinien verantwortlich?', 2, '[{"text": "Ja", "correct": true, "because": "Individuelle Pflicht"}, {"text": "Nein", "correct": false, "because": "Alle eingebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Verantwortung für Informationssicherheit im Anwendersupport dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweispflicht besteht"}, {"text": "Nein", "correct": false, "because": "Dokumentation erforderlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wer trägt die Hauptverantwortung für Informationssicherheit im Anwendersupport?', 2, '[{"text": "Geschäftsführung", "correct": true, "because": "Oberste Leitung verantwortlich"}, {"text": "IT-Team", "correct": false, "because": "Unterstützende Rolle"}, {"text": "Externe Berater", "correct": false, "because": "Nur beratend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle hat ein Datenschutzbeauftragter im Anwendersupport?', 3, '[{"text": "Überwachung", "correct": true, "because": "Kontrolliert Umsetzung"}, {"text": "Entwicklung", "correct": false, "because": "Nicht primäre Aufgabe"}, {"text": "Reparatur", "correct": false, "because": "Technische Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptaufgabe der Verantwortung im Anwendersupport?', 2, '[{"text": "Risiken minimieren", "correct": true, "because": "Schutz der Daten"}, {"text": "Software warten", "correct": false, "because": "Technische Aufgabe"}, {"text": "Support-Tickets lösen", "correct": false, "because": "Operative Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist im Anwendersupport für die Schulung zur Informationssicherheit verantwortlich?', 2, '[{"text": "Personalabteilung", "correct": true, "because": "Organisiert Schulungen"}, {"text": "Einzelne Mitarbeiter", "correct": false, "because": "Nur Teilnahme"}, {"text": "Kunden", "correct": false, "because": "Nicht involviert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz hat fehlende Verantwortung im Anwendersupport?', 2, '[{"text": "Sicherheitslücken", "correct": true, "because": "Unklare Zuständigkeiten"}, {"text": "Schnellere Problemlösung", "correct": false, "because": "Kein Vorteil"}, {"text": "Kosteneinsparung", "correct": false, "because": "Keine Ersparnis"}]'),

