('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben fallen unter die Verantwortung im Anwendersupport?', 4, '[{"text": "Richtlinien erstellen", "correct": true, "because": "Vorgaben setzen"}, {"text": "Schulungen durchführen", "correct": true, "because": "Sensibilisierung"}, {"text": "Sicherheitsvorfälle melden", "correct": true, "because": "Reaktion auf Probleme"}, {"text": "Hardware reparieren", "correct": false, "because": "Technische Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen hat unklare Verantwortung im Anwendersupport?', 3, '[{"text": "Datenschutzverletzungen", "correct": true, "because": "Fehlende Kontrolle"}, {"text": "Verzögerungen", "correct": true, "because": "Unklare Zuständigkeiten"}, {"text": "Rechtsverstöße", "correct": true, "because": "Gesetzesbruch möglich"}, {"text": "Schnellere Lösungen", "correct": false, "because": "Kein positiver Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen haben Verantwortung im Anwendersupport?', 4, '[{"text": "Überwachung", "correct": true, "because": "Kontrolle der Maßnahmen"}, {"text": "Umsetzung", "correct": true, "because": "Praktische Anwendung"}, {"text": "Dokumentation", "correct": true, "because": "Nachweisführung"}, {"text": "Marketing", "correct": false, "because": "Anderer Bereich"}]'),
