-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Geschäftsführung trägt Verantwortung für Informationssicherheit. b) Mitarbeiter haben keine Rolle dabei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Führung ja, Mitarbeiter auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verantwortung kann im Anwendersupport delegiert werden. b) Schulungen sind keine Pflicht der Verantwortung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Delegation ja, Schulungen Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verantwortung umfasst die Einhaltung von Richtlinien. b) Nur die IT-Abteilung ist dafür zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Richtlinien ja, alle beteiligt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Dokumentation ist Teil der Verantwortung im Anwendersupport. b) Verantwortung betrifft nur technische Maßnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verantwortung schließt Risikoanalyse ein. b) Kunden tragen die Hauptverantwortung für Sicherheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Risikoanalyse ja, Unternehmen verantwortlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

